INSERT INTO `npc_text` (`ID`, `text0_0`, `text0_1`, `BroadcastTextID0`, `lang0`, `Probability0`) VALUES
(9503200, 'Looking to trade, $c? I deal in Tarnished Undermine Reals and nothing else.$B$BThe bosses of Blackrock Mountain carry them. So does Onyxia, so do the trolls of Zul\'Gurub, whatever crawls in Ahn\'Qiraj and the dead of Naxxramas, and so do the ones in Stratholme, Scholomance and Dire Maul. A raid boss pays you once each time its raid resets, a dungeon boss once a day.$B$BDungeon sets I sell to anybody. What my crews hauled out of the raids I keep for people who finish a job: put Ragnaros down and I\'ll open the Molten Core crates. Onyxia, Nefarian, Hakkar, Ossirian, C\'Thun, Kel\'Thuzad: bring down any of them and I\'ll show you what came out of their halls.', 'Looking to trade, $c? I deal in Tarnished Undermine Reals and nothing else.$B$BThe bosses of Blackrock Mountain carry them. So does Onyxia, so do the trolls of Zul\'Gurub, whatever crawls in Ahn\'Qiraj and the dead of Naxxramas, and so do the ones in Stratholme, Scholomance and Dire Maul. A raid boss pays you once each time its raid resets, a dungeon boss once a day.$B$BDungeon sets I sell to anybody. What my crews hauled out of the raids I keep for people who finish a job: put Ragnaros down and I\'ll open the Molten Core crates. Onyxia, Nefarian, Hakkar, Ossirian, C\'Thun, Kel\'Thuzad: bring down any of them and I\'ll show you what came out of their halls.', 0, 0, 1);
