-- Who gives coins. `map` is the instance; `encounter` is a boss's DungeonEncounter.dbc id,
-- or 0 for every boss of the map that has no row of its own. `coins` 0 switches a row off:
-- on a boss's own row, that one boss.
-- The rows below are only added when missing, so your own changes to them stay; the
-- server reads the table at startup.
CREATE TABLE IF NOT EXISTS `mod_boss_coins_source` (
  `map` SMALLINT UNSIGNED NOT NULL,
  `encounter` INT UNSIGNED NOT NULL DEFAULT 0 COMMENT 'DungeonEncounter.dbc id; 0 = every boss of the map',
  `coins` TINYINT UNSIGNED NOT NULL DEFAULT 1,
  `comment` VARCHAR(255) NOT NULL DEFAULT '',
  PRIMARY KEY (`map`, `encounter`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='mod-boss-coins: bosses that give coins';

-- The creatures of bosses that the core's own credit doesn't fit. `encounter` is the boss's
-- DungeonEncounter.dbc id. A boss with rows here is paid by them alone, when the last of its
-- creatures in the instance dies (of those spawned from the creature table: summoned ones
-- aren't seen), so every creature of it has to be listed. Added when missing and read at
-- startup, like the table above.
CREATE TABLE IF NOT EXISTS `mod_boss_coins_credit` (
  `creature` INT UNSIGNED NOT NULL COMMENT 'creature_template entry',
  `encounter` INT UNSIGNED NOT NULL COMMENT 'DungeonEncounter.dbc id of the boss it is (part of)',
  `comment` VARCHAR(255) NOT NULL DEFAULT '',
  PRIMARY KEY (`creature`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='mod-boss-coins: the creatures of bosses paid on their last death';

-- What the launcher's shop sells, for coins from the account wallet. An offer is an item,
-- mailed to the character it is bought for, or a service the character gets at the
-- character list (`service` 1 rename, 2 customize, 3 race change, 4 faction change). An
-- offer whose item isn't on the server is left out. Ids below 1000 are this module's: what
-- they are follows the module, but `price`, `sort` and `enabled` are only set when an offer
-- is new, so prices you change stay. An offer the module no longer has is removed. Add your
-- own offers from 1000 on, they stay. `phase` is the mod-individual-progression phase the
-- account's furthest character must have reached before the offer can be bought. The
-- server reads the table at startup and on .coinshop reload.
CREATE TABLE IF NOT EXISTS `mod_boss_coins_shop` (
  `id` INT UNSIGNED NOT NULL,
  `category` VARCHAR(16) NOT NULL DEFAULT '' COMMENT 'the launcher groups offers by it: mount, pet, service, ...',
  `name` VARCHAR(64) NOT NULL DEFAULT '' COMMENT 'empty: the item\'s or the service\'s own name',
  `description` VARCHAR(255) NOT NULL DEFAULT '',
  `icon` VARCHAR(64) NOT NULL DEFAULT '' COMMENT 'Interface/Icons file name for the launcher; empty: the category\'s',
  `price` INT UNSIGNED NOT NULL COMMENT 'coins',
  `item` INT UNSIGNED NOT NULL DEFAULT 0 COMMENT 'item_template entry, mailed',
  `count` TINYINT UNSIGNED NOT NULL DEFAULT 1,
  `service` TINYINT UNSIGNED NOT NULL DEFAULT 0 COMMENT '1 rename, 2 customize, 3 race change, 4 faction change',
  `phase` TINYINT UNSIGNED NOT NULL DEFAULT 0 COMMENT 'mod-individual-progression phase the furthest character of the account must have reached; 0 = from the start',
  `sort` INT NOT NULL DEFAULT 0,
  `enabled` TINYINT UNSIGNED NOT NULL DEFAULT 1,
  `comment` VARCHAR(255) NOT NULL DEFAULT '',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='mod-boss-coins: the launcher shop';
-- Tables from before `phase` existed get the column. MySQL has no ADD COLUMN IF NOT EXISTS.
SET @phase_missing = (SELECT COUNT(*) = 0 FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'mod_boss_coins_shop' AND COLUMN_NAME = 'phase');
SET @sql = IF(@phase_missing, 'ALTER TABLE `mod_boss_coins_shop` ADD COLUMN `phase` TINYINT UNSIGNED NOT NULL DEFAULT 0 COMMENT \'mod-individual-progression phase the furthest character of the account must have reached; 0 = from the start\' AFTER `service`', 'DO 0');
PREPARE stmt FROM @sql;
EXECUTE stmt;
DEALLOCATE PREPARE stmt;
DELETE FROM `mod_boss_coins_shop` WHERE `id` < 1000 AND `id` NOT IN (1, 2, 3, 4, 101, 102, 103, 104, 105, 106, 107, 108, 109, 110, 201, 202, 203, 204, 205, 206, 207, 208, 209, 210, 211, 212, 213, 214, 215, 216, 217, 218, 219, 220, 221, 222, 223, 224, 225, 226, 227, 228, 229, 230, 231, 232, 233, 234, 235, 236, 237, 238, 239, 240, 241, 242, 243, 244, 245, 246, 247, 248, 249, 250, 251, 252, 253, 254, 255, 256, 257, 258, 259, 260, 261, 262, 263, 264, 265, 266, 267, 268, 269, 270, 271, 272, 273, 274, 275, 276);
ON DUPLICATE KEY UPDATE `category` = VALUES(`category`), `name` = VALUES(`name`), `description` = VALUES(`description`), `icon` = VALUES(`icon`), `phase` = VALUES(`phase`), `item` = VALUES(`item`), `count` = VALUES(`count`), `service` = VALUES(`service`), `comment` = VALUES(`comment`);
